def _bump_name(n):
    return n + '-x'

def run(api_names, parsed):
    counters = {}
    used = set()
    for idx, (kind, base, _spec) in enumerate(parsed):
        if kind != 'agent':
            continue
        n = counters.get(base.lower(), 0) + 1
        counters[base.lower()] = n
        candidate = base if n == 1 else f'{base}-{n}'
        while True:
            if candidate in api_names:
                raise ProviderError('seat name %r is used by both an agent seat and an API seat' % candidate)
            if candidate not in used:
                break
            candidate = _bump_name(candidate)
        used.add(candidate)
    return used

